+  async getSecret(name: string, defaultValue?: string): Promise<string | undefined> {
+    try {
+      const secret = await this.client.getSecret(name);
+      return secret.value;
+    } catch (error: any) {
+      if (error.statusCode === 404) {
+        return defaultValue;
+      }
+      throw error;
+    }
+  }
